1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ScenarioOutcome = {
6	  results: QuoteResult[];
7	};
8	
9	type Item = { type: string; cursed?: boolean; enchantment?: number };
10	
11	type Scenario = {
12	  steps: { items: Item[] }[];
13	};
14	
15	const PROCESSING_FEE = 5;
16	const FIRST_INSURANCE_SURCHARGE = 0.1;
17	const CURSE_SURCHARGE = 0.5;
18	const HIGH_ENCHANTMENT = 5;
19	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
20	
21	const BASE_PREMIUMS: Record<string, number> = {
22	  sword: 100,
23	  amulet: 60,
24	  staff: 80,
25	  potion: 40,
26	  rune: 25,
27	  moonstone: 25,
28	};
29	
30	const ALIKE_BLOCK_SIZE = 3;
31	const ALIKE_BLOCK_PREMIUM = 60;
32	
33	type AlikeGroup = [type: string, count: number];
34	
35	const groupAlikeItems = (items: Item[]): AlikeGroup[] => {
36	  const countByType = new Map<string, number>();
37	
38	  for (const item of items) {
39	    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
40	  }
41	
42	  return [...countByType];
43	};
44	
45	const ownBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
46	
47	const basePremiumOfGroup = ([type, count]: AlikeGroup): number => {
48	  if (count === ALIKE_BLOCK_SIZE) return ALIKE_BLOCK_PREMIUM;
49	
50	  return count * BASE_PREMIUMS[type];
51	};
52	
53	/**
54	 * The policy base premium: the sum of the item base premiums, with the
55	 * alike-block discount applied. Policy-scope modifiers are percentages OF
56	 * THIS amount — never of a total that already includes item surcharges.
57	 */
58	const policyBasePremiumOf = (items: Item[]): number =>
59	  groupAlikeItems(items)
60	    .map(basePremiumOfGroup)
61	    .reduce((total, groupPremium) => total + groupPremium, 0);
62	
63	/**
64	 * Item-scope surcharges: each is a percentage of the affected item's OWN base
65	 * premium, independent of the policy base and of the alike-block discount.
66	 */
67	const isCursed = (item: Item): boolean => item.cursed === true;
68	
69	const isHighlyEnchanted = (item: Item): boolean =>
70	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT;
71	
72	const surchargeRateOf = (item: Item): number =>
73	  (isCursed(item) ? CURSE_SURCHARGE : 0) +
74	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
75	
76	const itemSurchargesOf = (items: Item[]): number =>
77	  items.reduce((total, item) => total + ownBasePremiumOf(item) * surchargeRateOf(item), 0);
78	
79	/**
80	 * Policy-scope surcharges: each is a percentage of the policy base premium.
81	 */
82	const policySurchargesOn = (policyBase: number): number =>
83	  policyBase * FIRST_INSURANCE_SURCHARGE;
84	
85	const quotePremium = (items: Item[]): number => {
86	  const policyBase = policyBasePremiumOf(items);
87	  const premium =
88	    policyBase +
89	    itemSurchargesOf(items) +
90	    policySurchargesOn(policyBase) +
91	    PROCESSING_FEE;
92	
93	  return Math.ceil(premium);
94	};
95	
96	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
97	  results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
98	});
